// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetCategorizationStatistics Transactions dated in [from, to] by categorization method (SC5).
	// (GET /categorization-statistics)
	GetCategorizationStatistics(ctx context.Context, request GetCategorizationStatisticsRequestObject) (GetCategorizationStatisticsResponseObject, error)
	// ListCategorizations How the categories of several transactions were decided (A79).
	// (GET /categorizations)
	ListCategorizations(ctx context.Context, request ListCategorizationsRequestObject) (ListCategorizationsResponseObject, error)
	// ListPayeeAliases Payee aliases, oldest first.
	// (GET /payee-aliases)
	ListPayeeAliases(ctx context.Context, request ListPayeeAliasesRequestObject) (ListPayeeAliasesResponseObject, error)
	// CreatePayeeAlias Map raw descriptions to a payee (P5 amendment A22).
	// (POST /payee-aliases)
	CreatePayeeAlias(ctx context.Context, request CreatePayeeAliasRequestObject) (CreatePayeeAliasResponseObject, error)
	// DeletePayeeAlias Delete a payee alias.
	// (DELETE /payee-aliases/{id})
	DeletePayeeAlias(ctx context.Context, request DeletePayeeAliasRequestObject) (DeletePayeeAliasResponseObject, error)
	// GetPayeeAlias One payee alias.
	// (GET /payee-aliases/{id})
	GetPayeeAlias(ctx context.Context, request GetPayeeAliasRequestObject) (GetPayeeAliasResponseObject, error)
	// ChangePayeeAlias Replace a payee alias.
	// (PUT /payee-aliases/{id})
	ChangePayeeAlias(ctx context.Context, request ChangePayeeAliasRequestObject) (ChangePayeeAliasResponseObject, error)
	// ListRuleSuggestions Rules suggested from repeated manual corrections (P5 amendment A24).
	// (GET /rule-suggestions)
	ListRuleSuggestions(ctx context.Context, request ListRuleSuggestionsRequestObject) (ListRuleSuggestionsResponseObject, error)
	// AcceptRuleSuggestion Create the suggested rule at the last priority.
	// (POST /rule-suggestions/{id}/accept)
	AcceptRuleSuggestion(ctx context.Context, request AcceptRuleSuggestionRequestObject) (AcceptRuleSuggestionResponseObject, error)
	// DismissRuleSuggestion Dismiss a suggestion; it is not proposed again.
	// (POST /rule-suggestions/{id}/dismiss)
	DismissRuleSuggestion(ctx context.Context, request DismissRuleSuggestionRequestObject) (DismissRuleSuggestionResponseObject, error)
	// ListRules Categorization rules by priority.
	// (GET /rules)
	ListRules(ctx context.Context, request ListRulesRequestObject) (ListRulesResponseObject, error)
	// CreateRule Create a rule at the last priority.
	// (POST /rules)
	CreateRule(ctx context.Context, request CreateRuleRequestObject) (CreateRuleResponseObject, error)
	// PreviewRule What a rule would do alone over the transactions of the last 365 days (A81).
	// (POST /rules/preview)
	PreviewRule(ctx context.Context, request PreviewRuleRequestObject) (PreviewRuleResponseObject, error)
	// ReorderRules Give every rule a new priority, in the order listed.
	// (POST /rules/reorder)
	ReorderRules(ctx context.Context, request ReorderRulesRequestObject) (ReorderRulesResponseObject, error)
	// RunRules Run categorization (F5) on every uncategorized transaction.
	// (POST /rules/run)
	RunRules(ctx context.Context, request RunRulesRequestObject) (RunRulesResponseObject, error)
	// DeleteRule Delete a rule; categorizations it decided keep the method rule.
	// (DELETE /rules/{id})
	DeleteRule(ctx context.Context, request DeleteRuleRequestObject) (DeleteRuleResponseObject, error)
	// GetRule One rule.
	// (GET /rules/{id})
	GetRule(ctx context.Context, request GetRuleRequestObject) (GetRuleResponseObject, error)
	// ChangeRule Replace a rule; its priority does not change.
	// (PUT /rules/{id})
	ChangeRule(ctx context.Context, request ChangeRuleRequestObject) (ChangeRuleResponseObject, error)
	// ListSourceCategories Categories aggregators assigned to imported lines, by name (P6 amendment A41).
	// (GET /source-categories)
	ListSourceCategories(ctx context.Context, request ListSourceCategoriesRequestObject) (ListSourceCategoriesResponseObject, error)
	// MapSourceCategory Set the category of lines that carry the source category and no rule decides.
	// (PUT /source-categories/{id})
	MapSourceCategory(ctx context.Context, request MapSourceCategoryRequestObject) (MapSourceCategoryResponseObject, error)
	// GetCategorization How the categories of a transaction were decided (P5 amendment A20).
	// (GET /transactions/{id}/categorization)
	GetCategorization(ctx context.Context, request GetCategorizationRequestObject) (GetCategorizationResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

